himachalWorks['hans-raj'] = [
  {
    title: 'POCSO mamla: Churah ki yuvati ki shikayat par 7 Nov 2025 ko FIR, 27 Nov 2025 ko bail, Jan 2026 me chargesheet — 5 March 2026 se sunvai tay; MLA ne aarop kharij kiye',
    category: 'Any',
    badge: 'news',
    sourceLabel: 'The Tribune',
    sourceUrl: 'https://www.tribuneindia.com/news/himachal/chargesheet-filed-against-churah-mla-in-sexual-exploitation-case/',
    date: '2026-01-23',
    note: 'Yuvati ki shikayat par Chamba mahila police thana me 7 Nov 2025 ko Churah MLA Hans Raj ke khilaf POCSO Act (Sec 6) aur BNS Sec 69 ke tahat FIR darj hui — aarop tha ki nabalig avastha me jhoothi shadi ka bharosa dilakar sharirik sambandh banaye gaye; yuvati ne Chamba CJM court ke samaksh BNSS Sec 183 ke tahat bayan darj karaya (The Indian Express). 2024 me phone par ashleel message bhejne aur tasveeron ki maang ki shikayat par hui pehli FIR baad me wapas li gayi thi aur police ne closure report di thi (NDTV, Indian Express). MLA ke niji sahayak Lekh Chand aur sahyogi Muniyar Khan par bhi yuvati aur uske pita ke apaharan-dabav ki alag FIR darj hui (Indian Express). Hans Raj ne aarop be-buniyad aur siyasi sajish bataye, kaha ki ladki unke liye beti jaisi hai aur defamation case ka irada jataya (NDTV). 10 Nov ko agrim bail yachika, 11 Nov ko antarim aur 27 Nov 2025 ko niyamit bail mili; bail ke 2 mahine ke andar police ne chargesheet pesh kar di aur court ne 5 March 2026 se sunvai tay ki, jiske baad trial shuru hona hai — SP Chamba Vijay Kumar Saklani ne kaha janch nishpaksh aur tathya-aadharit hui (The Tribune). Amar Ujala (1 Mar 2026) ke anusaar mamla is waqt High Court me vicharadhin hai; Congress MLAs ne 27 Nov 2025 ko Vidhan Sabha gate par Hans Raj ke istife ki maang par virodh kiya (The Tribune).',
    period: '2022-2027',
  },
];

